/**
 * Top-level forecasting entry point. All numbers are produced here by
 * deterministic statistics; nothing is generated by a language model.
 */

import { rollingOriginBacktest, type BacktestResult } from "./backtest";
import { getForecaster, minHistoryFor } from "./baselines";
import { applyIntervals, calibrateIntervals } from "./intervals";
import { addDays, assertContiguous, assertValidSeries, type DailyPoint } from "./series";

export type RunForecastMethod = "seasonal_naive" | "drift" | "moving_average";

export interface RunForecastInput {
  /** Contiguous daily history (fill gaps explicitly with fillMissingDays first). */
  series: readonly DailyPoint[];
  horizonDays: number;
  method: RunForecastMethod;
  /** Default 7 (weekly). */
  seasonLength?: number;
  /** Clamp forecasts and lower bounds at 0 (counts, revenue). */
  nonNegative?: boolean;
  /**
   * Recorded for reproducibility. The current methods and empirical intervals
   * are fully deterministic, so the seed does not change results.
   */
  seed?: number;
  /** Moving-average window; defaults to seasonLength. */
  window?: number;
  /** Override calibration minimums (defaults: 20 residuals/bucket, 56 days). */
  minResidualsPerBucket?: number;
  minHistoryDays?: number;
}

export interface ForecastPoint {
  date: string;
  value: number;
  lo80?: number;
  hi80?: number;
  lo95?: number;
  hi95?: number;
}

export interface ForecastResult {
  status: "calibrated" | "insufficient_evidence";
  method: RunForecastMethod;
  points: ForecastPoint[];
  backtest: BacktestResult | null;
  calibration: {
    residualCounts: number[];
    bucketSize: number;
    heldOutCoverage80: number | null;
    heldOutCoverage95: number | null;
    heldOutCount: number;
    heldOutStartDate: string | null;
    reason: string | null;
  };
  assumptions: string[];
  warnings: string[];
}

function mean(xs: readonly number[]): number {
  let s = 0;
  for (const x of xs) s += x;
  return s / xs.length;
}

function sampleVariance(xs: readonly number[]): number {
  const m = mean(xs);
  let s = 0;
  for (const x of xs) s += (x - m) ** 2;
  return s / (xs.length - 1);
}

/**
 * Simple input-drift check: compares the mean of the last `window` days with
 * the prior `window` days using a Welch-style standard error. Returns a
 * description when |Δmean| > 3 SE. Uses whole weeks by default (28 days) so
 * weekly seasonality cancels in the means (it inflates the SE, making the
 * check conservative). Autocorrelation is ignored.
 */
export function detectInputDrift(values: readonly number[], window = 28, threshold = 3): string | null {
  if (values.length < 2 * window) return null;
  const recent = values.slice(-window);
  const prior = values.slice(-2 * window, -window);
  const diff = mean(recent) - mean(prior);
  const se = Math.sqrt(sampleVariance(recent) / window + sampleVariance(prior) / window);
  if ((se === 0 && diff !== 0) || (se > 0 && Math.abs(diff) > threshold * se)) {
    return `Input drift detected; review before using for decisions (last ${window}-day mean ${mean(recent).toFixed(2)} vs prior ${mean(prior).toFixed(2)}).`;
  }
  return null;
}

/**
 * Possible source outage: a trailing run of ≥ `minRun` zero days in a series
 * whose mean before the run is > 0. Zeros may be real; this only flags them.
 */
export function detectTrailingZeroOutage(values: readonly number[], minRun = 3): string | null {
  let run = 0;
  for (let i = values.length - 1; i >= 0 && values[i] === 0; i--) run++;
  if (run < minRun || run === values.length) return null;
  const prior = values.slice(0, values.length - run);
  if (mean(prior) > 0) {
    return `Possible data source outage: the last ${run} days are 0 after a non-zero history. Verify the integration before trusting this forecast.`;
  }
  return null;
}

/**
 * Produce a point forecast with empirically calibrated 80%/95% intervals.
 *
 * Steps: validate → point forecast on full history → rolling-origin backtest
 * (step 1, horizons 7/30/90 plus residuals up to horizonDays) → conformal
 * calibration with a held-out coverage check → drift/outage warnings.
 * Returns `insufficient_evidence` with NO numeric intervals when the evidence
 * thresholds are not met. Throws SeriesValidationError on invalid or gappy input.
 */
export function runForecast(input: RunForecastInput): ForecastResult {
  const m = input.seasonLength ?? 7;
  const window = input.window ?? m;
  const horizon = input.horizonDays;
  if (!Number.isInteger(horizon) || horizon < 1) throw new RangeError("horizonDays must be a positive integer");
  const series = assertValidSeries(input.series);
  assertContiguous(series);
  const values = series.map((p) => p.value);
  const nonNegative = input.nonNegative ?? false;

  const assumptions: string[] = [
    `Method: ${input.method}${input.method === "moving_average" ? ` (window ${window})` : ""}, season length ${m} days.`,
    "Point forecasts are fitted on all history up to the last observed day.",
    "Intervals are empirical: symmetric quantiles of absolute out-of-sample errors from a rolling-origin backtest (split-conformal style).",
    "Assumes future errors resemble past backtest errors (no structural change).",
    "Interval widths are forced non-decreasing with horizon.",
  ];
  if (nonNegative) assumptions.push("Metric is non-negative: forecasts and lower bounds are clamped at 0.");
  if (input.seed !== undefined) assumptions.push(`Seed ${input.seed} recorded; this method is deterministic.`);

  const warnings: string[] = [];
  const drift = detectInputDrift(values);
  if (drift) warnings.push(drift);
  const outage = detectTrailingZeroOutage(values);
  if (outage) warnings.push(outage);

  const lastDate = series.length ? series[series.length - 1].date : null;
  const minNeeded = minHistoryFor(input.method, m, window);
  if (series.length < minNeeded || lastDate === null) {
    return {
      status: "insufficient_evidence",
      method: input.method,
      points: [],
      backtest: null,
      calibration: {
        residualCounts: [],
        bucketSize: 7,
        heldOutCoverage80: null,
        heldOutCoverage95: null,
        heldOutCount: 0,
        heldOutStartDate: null,
        reason: `Method ${input.method} needs at least ${minNeeded} days of history; got ${series.length}.`,
      },
      assumptions,
      warnings,
    };
  }

  const clamp = (x: number) => (nonNegative ? Math.max(0, x) : x);
  const raw = getForecaster(input.method, m, window)(values, horizon);
  const pointValues = raw.map(clamp);

  const minTrainDays = Math.max(28, 2 * m + 1, minNeeded);
  const backtest =
    series.length > minTrainDays
      ? rollingOriginBacktest({
          series,
          method: input.method,
          horizons: [7, 30, 90],
          seasonLength: m,
          window,
          minTrainDays,
          step: 1,
          residualHorizon: horizon,
        })
      : null;

  const calibration = calibrateIntervals({
    residualRecords: backtest?.residualRecords ?? [],
    horizon,
    historyDays: series.length,
    historyDates: series.map((p) => p.date),
    minResidualsPerBucket: input.minResidualsPerBucket,
    minHistoryDays: input.minHistoryDays,
    nonNegative,
  });

  const points: ForecastPoint[] = pointValues.map((value, i) => ({ date: addDays(lastDate, i + 1), value }));
  if (calibration.status === "calibrated") {
    const bounds = applyIntervals(pointValues, calibration, nonNegative);
    bounds.forEach((b, i) => Object.assign(points[i], b));
    if (calibration.heldOut.coverage80 === null) {
      warnings.push(`Interval coverage not verified on held-out data: ${calibration.heldOut.reason ?? "unknown reason"}`);
    } else {
      assumptions.push(
        `Held-out coverage (targets from ${calibration.heldOut.startDate}, n=${calibration.heldOut.count}): 80% interval ${(calibration.heldOut.coverage80 * 100).toFixed(1)}%, 95% interval ${((calibration.heldOut.coverage95 ?? 0) * 100).toFixed(1)}%.`,
      );
    }
  }
  if (backtest) {
    for (const h of backtest.byHorizon) {
      if (h.beatsBaseline === false && input.method !== "seasonal_naive") {
        warnings.push(`At ${h.horizon}-day horizon the ${input.method} method did not beat the seasonal-naive baseline in backtest.`);
      }
    }
  }

  return {
    status: calibration.status,
    method: input.method,
    points,
    backtest,
    calibration: {
      residualCounts: calibration.residualCounts,
      bucketSize: calibration.bucketSize,
      heldOutCoverage80: calibration.heldOut.coverage80,
      heldOutCoverage95: calibration.heldOut.coverage95,
      heldOutCount: calibration.heldOut.count,
      heldOutStartDate: calibration.heldOut.startDate,
      reason: calibration.reason,
    },
    assumptions,
    warnings,
  };
}
